<?php $this->load->view('stripe_hub/_header'); ?>
<?php if(is_admin() || staff_can('delete','stripe_hub')){ ?><div class="panel_s"><div class="panel-body"><h4><?= _l('stripe_hub_create_refund'); ?></h4><?= form_open(admin_url('stripe_hub/create_refund')); ?><div class="row"><div class="col-md-5"><?= render_input('payment_intent','stripe_hub_payment_intent'); ?></div><div class="col-md-3"><?= render_input('amount','stripe_hub_refund_amount_optional','', 'number',['step'=>'0.01','min'=>'0.01']); ?></div><div class="col-md-4"><?= render_select('reason',[['id'=>'requested_by_customer','name'=>_l('stripe_hub_reason_requested')],['id'=>'duplicate','name'=>_l('stripe_hub_reason_duplicate')],['id'=>'fraudulent','name'=>_l('stripe_hub_reason_fraudulent')]],['id','name'],'stripe_hub_reason'); ?></div></div><button type="submit" class="btn btn-danger" onclick="return confirm('<?= e(_l('stripe_hub_refund_confirm')); ?>');"><?= _l('stripe_hub_refund'); ?></button><?= form_close(); ?></div></div><?php } ?>
<div class="panel_s"><div class="panel-body"><h4><?= _l('stripe_hub_refunds'); ?></h4><?php if($refunds){ ?><div class="table-responsive"><table class="table dt-table"><thead><tr><th><?= _l('stripe_hub_id'); ?></th><th><?= _l('stripe_hub_amount'); ?></th><th><?= _l('stripe_hub_status'); ?></th><th><?= _l('stripe_hub_payment_intent'); ?></th><th><?= _l('stripe_hub_date'); ?></th></tr></thead><tbody><?php foreach($refunds->data as $r){ ?><tr><td><code><?= e($r->id); ?></code></td><td><?= e(strtoupper($r->currency).' '.number_format($r->amount/100,2)); ?></td><td><?= e($r->status); ?></td><td><?= e($r->payment_intent ?: '-'); ?></td><td><?= e(date('Y-m-d H:i',$r->created)); ?></td></tr><?php } ?></tbody></table></div><?php } else { ?><p class="text-muted"><?= _l('stripe_hub_global_permission_required'); ?></p><?php } ?></div></div>
